/* Section reveals, as on Belgrade Arbor: each one plays once when its section is 70% up the screen
   (the footer as soon as it appears). Checked on scroll, since clip-path hides elements from IntersectionObserver. */
(function () {
  "use strict";
  if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
  var sc = document.getElementById("scroller");
  var foot = document.querySelector(".foot");
  if (foot) Array.prototype.forEach.call(foot.querySelectorAll(".foot-grid > *, .foot-mark, .foot-legal"), function (el, i) { el.classList.add("f-fade"); el.style.setProperty("--i", i); });
  var items = Array.prototype.slice.call(document.querySelectorAll(".rvl, .rvl-wipe")).map(function (el) { return { el: el, at: 0.7 }; });
  if (foot) items.push({ el: foot, at: 0.98 });
  if (!items.length) return;
  document.documentElement.classList.add("js-rvl");
  var ticking = false;
  function check() {
    ticking = false;
    var vh = window.innerHeight;
    items = items.filter(function (it) {
      var r = it.el.getBoundingClientRect();
      if (r.top < vh * it.at && r.bottom > 0) { it.el.classList.add("in"); return false; }
      return true;
    });
    if (!items.length) { (sc || window).removeEventListener("scroll", onScroll); window.removeEventListener("resize", onScroll); }
  }
  function onScroll() { if (!ticking) { ticking = true; requestAnimationFrame(check); } }
  (sc || window).addEventListener("scroll", onScroll, { passive: true });
  window.addEventListener("resize", onScroll);
  requestAnimationFrame(function () { requestAnimationFrame(check); });
})();




